var result=new List<object>();
foreach(var e in new FilteredElementCollector(document).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>().Where(e=>new[]{"RT-T1-01-TC1-L","RT-T1-01-BC+1T","RT-T5-01-TC1"}.Contains(e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString()))){
var tr=e.GetTransform();var vertices=new List<XYZ>();Action<GeometryElement> collect=null;collect=g=>{foreach(var o in g){if(o is Solid s&&s.Volume>1e-9){foreach(Edge ed in s.Edges)vertices.AddRange(ed.Tessellate());}else if(o is GeometryInstance gi)collect(gi.GetInstanceGeometry());}};collect(e.get_Geometry(new Options{DetailLevel=ViewDetailLevel.Fine}));var c=((LocationCurve)e.Location).Curve;var a=c.GetEndPoint(0);var b=c.GetEndPoint(1);var u=(b-a).Normalize();var local=vertices.Select(p=>tr.Inverse.OfPoint(p)*304.8).ToList();
result.Add(new{mark=e.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString(),a=new[]{a.X*304.8,a.Y*304.8,a.Z*304.8},b=new[]{b.X*304.8,b.Y*304.8,b.Z*304.8},axisLength=c.Length*304.8,extentAlong=new[]{vertices.Min(p=>(p-a).DotProduct(u)*304.8),vertices.Max(p=>(p-a).DotProduct(u)*304.8)},localMin=new[]{local.Min(p=>p.X),local.Min(p=>p.Y),local.Min(p=>p.Z)},localMax=new[]{local.Max(p=>p.X),local.Max(p=>p.Y),local.Max(p=>p.Z)},parameters=e.Parameters.Cast<Parameter>().Where(p=>p.StorageType==StorageType.Double).Select(p=>new{name=p.Definition.Name,value=p.AsDouble()}).ToArray()});}
var roofs=new FilteredElementCollector(document).OfClass(typeof(FootPrintRoof)).Cast<FootPrintRoof>().Select(r=>new{mark=r.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString(),z=r.get_Parameter(BuiltInParameter.ROOF_LEVEL_OFFSET_PARAM).AsDouble()*304.8,faces=r.get_Geometry(new Options()).OfType<Solid>().SelectMany(s=>s.Faces.Cast<Face>()).OfType<PlanarFace>().Select(f=>new{origin=new[]{f.Origin.X*304.8,f.Origin.Y*304.8,f.Origin.Z*304.8},normal=new[]{f.FaceNormal.X,f.FaceNormal.Y,f.FaceNormal.Z}}).ToArray()}).ToArray();return new{members=result,roofs};
